const SCOPE_PATH = new URL(self.registration.scope).pathname;

let pcRunning = false;

function plainAssetRequest(urlLike) {
  const url = new URL(urlLike, self.registration.scope);
  return new Request(url.origin + url.pathname);
}

function relativeAssetPath(urlLike) {
  const url = new URL(urlLike, self.registration.scope);
  let path = url.pathname;
  if (path.indexOf(SCOPE_PATH) === 0) path = path.slice(SCOPE_PATH.length);
  return path.replace(/^\/+/, '');
}

function assetHash(urlLike) {
  return ASSET_META[relativeAssetPath(urlLike)] || '';
}

function assetCacheKey(urlLike) {
  const url = new URL(urlLike, self.registration.scope);
  url.search = '';
  url.hash = '';
  const hash = assetHash(url.href);
  if (hash) url.searchParams.set('__asset_v', hash);
  return url.href;
}

function digestHex(buffer) {
  if (!self.crypto || !self.crypto.subtle) return Promise.resolve('');
  return self.crypto.subtle.digest('SHA-256', buffer).then(function (digest) {
    return Array.from(new Uint8Array(digest)).map(function (byte) {
      return byte.toString(16).padStart(2, '0');
    }).join('');
  });
}

function responseMatchesHash(response, hash) {
  if (!hash) return Promise.resolve(false);
  return response.clone().arrayBuffer().then(digestHex).then(function (actual) {
    return actual === hash;
  }).catch(function () {
    return false;
  });
}

function matchAsset(cache, urlLike) {
  const key = assetCacheKey(urlLike);
  const hash = assetHash(urlLike);
  return cache.match(key).then(function (hit) {
    if (hit || !hash) return hit;
    return caches.keys().then(function (names) {
      const legacy = names.filter(function (name) {
        return name !== ASSET_CACHE &&
          (name.indexOf('woxi-web-') === 0 || name.indexOf('woxi-shell-') === 0);
      });
      function next(index) {
        if (index >= legacy.length) return null;
        return caches.open(legacy[index]).then(function (oldCache) {
          return oldCache.match(plainAssetRequest(urlLike));
        }).then(function (oldResponse) {
          if (!oldResponse) return next(index + 1);
          return responseMatchesHash(oldResponse, hash).then(function (same) {
            if (!same) return next(index + 1);
            const copy = oldResponse.clone();
            return cache.put(key, oldResponse).then(function () { return copy; });
          });
        });
      }
      return next(0);
    });
  });
}

function putAsset(cache, urlLike, response) {
  return cache.put(assetCacheKey(urlLike), response);
}

function pcCount() {
  return caches.open(ASSET_CACHE).then(function (cache) {
    let done = 0;
    return Promise.all(CHASE.map(function (url) {
      return cache.match(assetCacheKey(url)).then(function (hit) {
        if (hit) done += 1;
      });
    })).then(function () { return done; });
  });
}

function pcTell(state) {
  return pcCount().then(function (done) {
    const message = { type: 'wc', state: state, done: done, total: CHASE.length };
    return self.clients.matchAll({ includeUncontrolled: true }).then(function (clients) {
      clients.forEach(function (client) {
        try { client.postMessage(message); } catch (error) {}
      });
    });
  }).catch(function () {});
}

function pcFetch(url, timeoutMs) {
  return new Promise(function (resolve, reject) {
    let finished = false;
    const controller = ('AbortController' in self) ? new AbortController() : null;
    const timer = setTimeout(function () {
      if (finished) return;
      finished = true;
      if (controller) {
        try { controller.abort(); } catch (error) {}
      }
      reject(new Error('timeout ' + url));
    }, timeoutMs);
    fetch(url, {
      credentials: 'same-origin',
      cache: 'no-cache',
      signal: controller ? controller.signal : undefined
    }).then(function (response) {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      resolve(response);
    }).catch(function (error) {
      if (finished) return;
      finished = true;
      clearTimeout(timer);
      reject(error);
    });
  });
}

function runPrecache() {
  if (pcRunning) return;
  pcRunning = true;
  caches.open(ASSET_CACHE).then(function (cache) {
    const missing = [];
    return Promise.all(CHASE.map(function (url) {
      return matchAsset(cache, url).then(function (hit) {
        if (!hit) missing.push(url);
      });
    })).then(function () {
      if (!missing.length) {
        pcRunning = false;
        return pcTell('done');
      }
      let index = 0;
      let doneCount = CHASE.length - missing.length;
      let failed = 0;
      pcTell('running');

      function one() {
        if (index >= missing.length) return Promise.resolve();
        const url = missing[index++];
        let tries = 0;
        function attempt() {
          tries += 1;
          return pcFetch(url, 20000).then(function (response) {
            if (!response || !response.ok) throw new Error('bad ' + url);
            return putAsset(cache, url, response.clone());
          }).then(function () {
            doneCount += 1;
            if (doneCount % 3 === 0 || doneCount >= CHASE.length) pcTell('running');
            return one();
          }).catch(function () {
            if (tries < 2) {
              return new Promise(function (resolve) {
                setTimeout(resolve, 1200 * tries);
              }).then(attempt);
            }
            failed += 1;
            return one();
          });
        }
        return attempt();
      }

      return Promise.all([one(), one()]).then(function () {
        pcRunning = false;
        return pcTell(failed ? 'error' : 'done');
      });
    });
  }).catch(function () {
    pcRunning = false;
    pcTell('error');
  });
}

self.addEventListener('install', function (event) {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys().then(function (names) {
      return Promise.all(names.filter(function (name) {
        return name.indexOf('woxi-shell-') === 0 && name !== CACHE;
      }).map(function (name) {
        return caches.delete(name);
      }));
    }).then(function () {
      return self.clients.claim();
    }).then(function () {
      runPrecache();
    })
  );
});

self.addEventListener('message', function (event) {
  const data = event.data || {};
  if (data.type === 'wc-start') runPrecache();
});

self.addEventListener('fetch', function (event) {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request, { cache: 'no-store' }).then(function (response) {
        if (response && response.ok) {
          const copy = response.clone();
          event.waitUntil(caches.open(CACHE).then(function (cache) {
            return cache.put('./index.html', copy);
          }));
        }
        return response;
      }).catch(function () {
        return caches.open(CACHE).then(function (cache) {
          return cache.match('./index.html').then(function (fallback) {
            return fallback || new Response('离线，而且本机还没有下载过这一页。', {
              status: 503,
              headers: { 'Content-Type': 'text/plain; charset=utf-8' }
            });
          });
        });
      })
    );
    return;
  }

  if (assetHash(request.url)) {
    event.respondWith(
      caches.open(ASSET_CACHE).then(function (cache) {
        return matchAsset(cache, request.url).then(function (hit) {
          if (hit) return hit;
          return fetch(request, { cache: 'no-cache' }).then(function (response) {
            if (response && response.ok) {
              event.waitUntil(putAsset(cache, request.url, response.clone()));
            }
            return response;
          }).catch(function () {
            return new Response('', {
              status: 503,
              statusText: 'offline asset unavailable'
            });
          });
        });
      })
    );
    return;
  }

  event.respondWith(
    caches.open(CACHE).then(function (cache) {
      return cache.match(request, { ignoreSearch: true }).then(function (hit) {
        if (hit) return hit;
        return fetch(request, { cache: 'no-cache' }).then(function (response) {
          if (response && response.ok) event.waitUntil(cache.put(request, response.clone()));
          return response;
        }).catch(function () {
          return new Response('', {
            status: 503,
            statusText: 'offline asset unavailable'
          });
        });
      });
    })
  );
});
